    html{scroll-behavior:smooth;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}
    body{background:var(--bg);color:var(--text);font-family:var(--font-sans);line-height:1.6;overflow-x:hidden}
    a{color:inherit;text-decoration:none}
    ::selection{background:var(--terracotta);color:var(--bg)}

    .nav{position:fixed;top:0;left:0;right:0;z-index:100;padding:24px 40px;display:flex;justify-content:space-between;align-items:center;background:var(--bg)}
    .nav-logo{font-family:var(--font-serif);font-size:20px;font-weight:700;color:var(--text);letter-spacing:-0.02em}
    .nav-links{display:flex;gap:32px;list-style:none}
    .nav-links a{font-size:13px;font-weight:500;color:var(--text);letter-spacing:0.04em;text-transform:uppercase;transition:opacity .2s}
    .nav-links a:hover{opacity:.5}
    .nav-links a.active{color:var(--terracotta)}
    .hamburger{display:none;background:none;border:none;cursor:pointer;padding:4px;z-index:200}
    .hamburger span{display:block;width:24px;height:1.5px;background:var(--text);margin:6px 0;transition:all .3s cubic-bezier(.4,0,.2,1)}
    .hamburger.active span:nth-child(1){transform:rotate(45deg) translate(5px,5px)}
    .hamburger.active span:nth-child(2){opacity:0}
    .hamburger.active span:nth-child(3){transform:rotate(-45deg) translate(6px,-6px)}
    .mobile-overlay{position:fixed;inset:0;background:var(--text);z-index:150;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:32px;opacity:0;pointer-events:none;transition:opacity .4s cubic-bezier(.4,0,.2,1)}
    .mobile-overlay.active{opacity:1;pointer-events:auto}
    .mobile-overlay a{font-family:var(--font-serif);font-size:36px;color:var(--bg);opacity:0;transform:translateY(20px);transition:all .4s cubic-bezier(.4,0,.2,1)}
    .mobile-overlay.active a{opacity:1;transform:translateY(0)}
    .mobile-overlay.active a:nth-child(1){transition-delay:.1s}
    .mobile-overlay.active a:nth-child(2){transition-delay:.15s}
    .mobile-overlay.active a:nth-child(3){transition-delay:.2s}
    .mobile-overlay.active a:nth-child(4){transition-delay:.25s}
    .mobile-overlay.active a:nth-child(5){transition-delay:.3s}

    /* ── Contact Hero ── */
    .contact{min-height:100vh;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;padding:120px 40px}
    .contact-heading{font-family:var(--font-serif);font-size:clamp(80px,18vw,280px);font-weight:700;line-height:.85;letter-spacing:-0.04em;margin-bottom:64px}
    .contact-links{display:flex;flex-direction:column;gap:16px;align-items:center}
    .contact-links a{font-size:18px;font-weight:500;color:var(--text-secondary);letter-spacing:0.02em;transition:color .2s;position:relative}
    .contact-links a:hover{color:var(--terracotta)}
    .contact-links a::after{content:'';position:absolute;bottom:-2px;left:0;right:0;height:1px;background:var(--terracotta);transform:scaleX(0);transition:transform .3s cubic-bezier(.4,0,.2,1)}
    .contact-links a:hover::after{transform:scaleX(1)}

    /* ── Footer ── */
    .footer{padding:60px 40px;border-top:1px solid rgba(26,26,26,.1);display:flex;justify-content:space-between;align-items:center}
    .footer-copy{font-size:13px;color:var(--text-tertiary)}
    .footer-links{display:flex;gap:24px}
    .footer-links a{font-size:13px;color:var(--text-tertiary);transition:color .2s}
    .footer-links a:hover{color:var(--text)}

    @media(max-width:768px){
      .nav{padding:20px 24px}
      .nav-links{display:none}
      .hamburger{display:block}
      .contact{padding:100px 24px;min-height:85vh}
      .contact-heading{font-size:clamp(64px,22vw,140px);margin-bottom:48px}
      .contact-links a{font-size:16px}
      .footer{padding:40px 24px;flex-direction:column;gap:16px;align-items:flex-start}
    }
  </style>
